function () {
    'use strict';

    const api = window.MaterialDetectorAPI;
    if (!api) return;

    const BUTTON_ID = 'materialDetectorConfigButton';
    const PANEL_ID = 'materialDetectorConfigPanel';
    const ACTION_PANEL_ID = 'fc-userscripts-action-panel';
    const DEFAULT_TOKENS = [
        'alias', 'size', 'quantity', 'vp', 'detector', 'code', 'productCode',
        'mediaType', 'mediaTypeRaw', 'weight', 'variant', 'material', 'materialAlias',
        'colorCode', 'folding', 'kind', 'canvas', 'giftPack', 'aliasKey', 'original', 'ext'
    ];

    let initialized = false;
    let selectedDetectorId = '';
    let onChange = function () {};

    function esc(value) {
        return String(value == null ? '' : value)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }

    function getPanelTop() {
        const topRow = document.querySelector('#top-row');
        if (!topRow) return 94;
        return Math.max(8, Math.round(topRow.getBoundingClientRect().bottom + 8));
    }

    function ensureActionPanel() {
        if (window.FCUserscripts && typeof window.FCUserscripts.ensureActionPanel === 'function') {
            return window.FCUserscripts.ensureActionPanel();
        }
        let panel = document.getElementById(ACTION_PANEL_ID);
        if (panel) return panel;
        panel = document.createElement('div');
        panel.id = ACTION_PANEL_ID;
        Object.assign(panel.style, {
            position: 'fixed', right: '20px', top: `${getPanelTop()}px`, bottom: 'auto', zIndex: '900',
            width: '94px', display: 'flex', flexDirection: 'column', alignItems: 'stretch', gap: '5px'
        });
        document.body.appendChild(panel);
        return panel;
    }

    function styleActionButton(button) {
        if (window.FCUserscripts && typeof window.FCUserscripts.styleActionButton === 'function') {
            window.FCUserscripts.styleActionButton(button, { background: '#263238', borderColor: '#111' });
            return;
        }
        Object.assign(button.style, {
            position: 'static', right: 'auto', bottom: 'auto', display: 'block', width: '100%', minWidth: '0',
            boxSizing: 'border-box', margin: '0', padding: '8px 10px', textAlign: 'center', lineHeight: '13px',
            fontWeight: '700', color: '#fff', background: '#263238', border: '1px solid #111', borderRadius: '5px',
            cursor: 'pointer', boxShadow: '0 2px 8px rgba(0,0,0,0.18)', textDecoration: 'none'
        });
    }

    function ensureButton() {
        if (!document.body) return null;
        const actionPanel = ensureActionPanel();
        let button = document.getElementById(BUTTON_ID);
        if (!button) {
            button = document.createElement('a');
            button.id = BUTTON_ID;
            button.href = 'javascript:void(0)';
            button.textContent = 'MD CFG';
            button.title = 'MaterialDetector konfiguracia';
            button.addEventListener('click', togglePanel);
        }
        styleActionButton(button);
        if (button.parentNode !== actionPanel) actionPanel.appendChild(button);
        return button;
    }

    function addStyles() {
        if (document.getElementById('materialDetectorConfigStyles')) return;
        const style = document.createElement('style');
        style.id = 'materialDetectorConfigStyles';
        style.textContent = `
            #${PANEL_ID}{position:fixed;right:124px;top:94px;width:470px;max-width:calc(100vw - 150px);max-height:82vh;overflow:auto;z-index:901;background:#fff;color:#111;border:1px solid #222;border-radius:6px;box-shadow:0 8px 28px rgba(0,0,0,.32);font-family:Arial,sans-serif;font-size:12px;display:none}
            #${PANEL_ID} *{box-sizing:border-box} #${PANEL_ID} .mdcp-head{display:flex;align-items:center;justify-content:space-between;padding:10px 12px;background:#111;color:#fff;font-weight:700}
            #${PANEL_ID} .mdcp-body{padding:12px} #${PANEL_ID} label{display:block;font-weight:700;margin:9px 0 4px}
            #${PANEL_ID} select,#${PANEL_ID} input{width:100%;border:1px solid #bbb;border-radius:4px;padding:6px;font-size:12px}
            #${PANEL_ID} button{border:1px solid #333;border-radius:4px;background:#f4f4f4;padding:5px 7px;cursor:pointer;font-size:12px}
            #${PANEL_ID} button.primary{background:#111;color:#fff} #${PANEL_ID} button.danger{background:#b71c1c;color:#fff;border-color:#7f0000}
            #${PANEL_ID} .mdcp-row{display:flex;gap:6px;align-items:center;margin:5px 0} #${PANEL_ID} .mdcp-row>*{flex:1} #${PANEL_ID} .mdcp-row button{flex:0 0 auto}
            #${PANEL_ID} .mdcp-block{border:1px solid #ddd;background:#fafafa;border-radius:4px;padding:6px;margin:5px 0;cursor:grab}
            #${PANEL_ID} .mdcp-preview{background:#f5f5f5;border:1px solid #ddd;border-radius:4px;padding:8px;white-space:pre-wrap;font-family:monospace;max-height:130px;overflow:auto}
            #${PANEL_ID} .mdcp-actions{display:flex;gap:7px;margin-top:12px;flex-wrap:wrap} #${PANEL_ID} .mdcp-small{color:#555;font-size:11px;line-height:1.35}
            #${PANEL_ID} .mdcp-token{display:inline-block;background:#111;color:#fff;border-radius:4px;padding:2px 5px;margin:2px;font-family:monospace}
            #${PANEL_ID} .mdcp-section{border-top:1px solid #ddd;margin-top:12px;padding-top:10px}
        `;
        document.head.appendChild(style);
    }

    function ensurePanel() {
        addStyles();
        let panel = document.getElementById(PANEL_ID);
        if (panel) return panel;
        panel = document.createElement('div');
        panel.id = PANEL_ID;
        document.body.appendChild(panel);
        return panel;
    }

    function getDetectors() {
        return api.getDetectors().filter(detector => detector && detector.id);
    }

    function getSelectedDetector() {
        const detectors = getDetectors();
        const state = window.__materialDetectorState || {};
        if (!selectedDetectorId) selectedDetectorId = state.detector || (detectors[0] && detectors[0].id) || '';
        return detectors.find(detector => detector.id === selectedDetectorId) || detectors[0] || null;
    }

    function getTokenList(detector) {
        const own = Array.isArray(detector && detector.tokens) ? detector.tokens : [];
        return Array.from(new Set([...own, ...DEFAULT_TOKENS]));
    }

    function getCurrentRenameEnabled(settings) {
        if (typeof settings.renameEnabled === 'boolean') return settings.renameEnabled;
        const state = window.__materialDetectorState || {};
        return !!(state.detector === selectedDetectorId && state.rename && state.rename.enabled === true);
    }

    function tokenPreview() {
        const tokens = Object.assign({}, (window.__materialDetectorState || {}).tokens || {}, window.__materialDetectorTokens || {});
        return Object.keys(tokens).sort().map(key => `${key}: ${tokens[key]}`).join('\n') || 'Tokeny zatial nie su dostupne.';
    }

    function detectorPreview() {
        const state = window.__materialDetectorState || {};
        return [
            `detector: ${state.detector || ''}`,
            `productCode: ${state.productCode || ''}`,
