            optionMode: mode,
            constructionType,
            constructionAlias,
            constructionOnlyAlias: constructionAlias,
            printAlias,
            quality,
            qualityAlias: qAlias,
            printType: getParam(params, ['tlac']),
            printArea: getParam(params, ['vypocitane pole tlac']),
            printSubstrate: getParam(params, ['tlacovy podklad']),
