                await setGrafikaTag(vpId);
                await assignToGrafikaQueue(vpId);

                setButtonState(button, 'HOTOVO', true);
                showToast('VP bolo uspesne zaradene do grafiky.');
                console.log('[DO GRAFIKY] VP uspesne zaradene do grafiky.');

                await sleep(1400);
                window.location.reload();
            } catch (error) {
                console.error('[DO GRAFIKY] Chyba:', error);
                setButtonState(button, DEFAULT_LABEL, false);
                showToast(`DO GRAFIKY zlyhalo: ${error.message}`, 'error');
            }
        }, true);

        vfButton.parentNode.insertBefore(button, vfButton);
        console.log('[DO GRAFIKY] Button pridany do povodneho radu akcii bez zasahu do layoutu webu.');
    }

    function init() {
        let tries = 0;

        const interval = setInterval(() => {
            tries += 1;

            const vfButton = [...document.querySelectorAll('a.datatable-add.button.green.small')]
                .find((button) => (button.getAttribute('onclick') || '').includes('showVpSingleForm('));

